pasará la tierra,
mas tus palabras no pasarán.
Aleluya, aleluya.','','Do','aleluya',NULL,NULL,NULL,NULL,'betaniamusic.blogspot.com','2026-09-15 10:26:15','[{"tipo": "acordes", "acordes": [{"acorde": "Do", "posicion": 0}, {"acorde": "Sol", "posicion": 3}], "letra": "", "texto": "", "acordes_raw": "Do       Sol"}, {"tipo": "vacía", "acordes": [], "letra": "", "texto": "", "acordes_raw": ""}, {"tipo": "letra", "acordes": [], "letra": "Ale, aleluya,", "texto": "", "acordes_raw": ""}, {"tipo": "vacía", "acordes": [], "letra": "", "texto": "", "acordes_raw": ""}, {"tipo": "acordes", "acordes": [{"acorde": "Lam", "posicion": 0}, {"acorde": "Mim", "posicion": 4}], "letra": "", "texto": "", "acordes_raw": "Lam       Mim"}, {"tipo": "vacía", "acordes": [], "letra": "", "texto": "", "acordes_raw": ""}, {"tipo": "letra", "acordes": [], "letra": "aleluya, aleluya,", "texto": "", "acordes_raw": ""}, {"tipo": "vacía", "acordes": [], "letra": "", "texto": "", "acordes_raw": ""}, {"tipo": "acordes", "acordes": [{"acorde": "Fa", "posicion": 0}, {"acorde": "Do", "posicion": 3}], "letra": "", "texto": "", "acordes_raw": " Fa          Do"}, {"tipo": "acordes", "acordes": [{"acorde": "Rem", "posicion": 0}], "letra": "", "texto": "", "acordes_raw": "Rem"}, {"tipo": "vacía", "acordes": [], "letra": "", "texto": "", "acordes_raw": ""}, {"tipo": "letra", "acordes": [], "letra": "aleluya, aleluya,", "texto": "", "acordes_raw": ""}, {"tipo": "vacía", "acordes": [], "letra": "", "texto": "", "acordes_raw": ""}, {"tipo": "acordes", "acordes": [{"acorde": "Lam", "posicion": 0}, {"acorde": "Fa", "posicion": 4}, {"acorde": "Sol", "posicion": 7}], "letra": "", "texto": "", "acordes_raw": "Lam Fa    Sol"}, {"tipo": "acordes", "acordes": [{"acorde": "Do", "posicion": 0}], "letra": "", "texto": "", "acordes_raw": "Do"}, {"tipo": "vacía", "acordes": [], "letra": "", "texto": "", "acordes_raw": ""}, {"tipo": "letra", "acordes": [], "letra": "aleluya, aleluya.", "texto": "", "acordes_raw": ""}, {"tipo": "vacía", "acordes": [], "letra": "", "texto": ""